// The backup page. Its job is to tell the truth about three layers, including
// the two that do not exist yet — a backup page that only lists what works
// is how "collected by Restic" survived unchallenged for a month.

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

let v = {};
try { v = $('Host vitals').first().json || {}; } catch (e) { v = {}; }
if (v.body) v = typeof v.body === 'string' ? JSON.parse(v.body) : v.body;

const hasVitals = Boolean(v.generated);
const hrs = (h) => h < 0 ? 'never' : h < 1 ? 'under an hour ago'
  : h < 48 ? h + ' hours ago' : Math.round(h / 24) + ' days ago';

const COLOUR = { green:'#0b6e4f', amber:'#b8860b', red:'#990000', grey:'#5a6068' };
const dot = (s) => `<span class="dot" style="background:${COLOUR[s] || COLOUR.grey}"></span>`;

// Layer 1: the nightly application dumps — live today, same disk as the
// services, so honest wording matters: staging area, not disaster copy.
const SCHEDULE = { espocrm: '02:30', n8n: '02:45', meshcentral: '03:15' };
const dumps = (v.backups || []).map(b => ({
  ...b,
  when: SCHEDULE[b.name] || '',
  state: b.ageHours < 0 || b.ageHours > 72 ? 'red' : b.ageHours > 36 ? 'amber' : 'green',
}));
const dumpRows = dumps.length ? dumps.map(b =>
  `<tr><td>${dot(b.state)}${esc(b.name)}</td><td>${esc(b.when)} nightly</td>
   <td class="r">${esc(hrs(b.ageHours))}</td></tr>`).join('')
  : `<tr><td colspan="3" class="quiet">${hasVitals
      ? 'No dump directories reported.' : 'Host snapshot unavailable.'}</td></tr>`;

// What each layer means for the business, in plain words.
const coverage = [
  ['CRM contacts, meetings, bookings', 'espocrm dump', 'green'],
  ['n8n workflows & credentials',      'n8n dump (workflows also in GitHub)', 'green'],
  ['MeshCentral keys — customer agents die without them', 'meshcentral dump', 'green'],
  ['All infrastructure & configuration', 'GitHub — rebuildable in an afternoon', 'green'],
  ['Invoices, payments, the books',    'Xero & Stripe hold these (SaaS)', 'green'],
  ['Email & calendar',                 'Microsoft 365 (SaaS)', 'green'],
];

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@600&display=swap" rel="stylesheet">
<title>IT Surgery — Backup</title>
<style>
 :root{--brand:#990000;--ink:#333;--strong:#222;--quiet:#5a6068;--line:#dcdfe3;--bg:#f4f5f7}
 *{box-sizing:border-box}
 body{margin:0;background:var(--bg);color:var(--ink);
   font:14px/1.45 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif}
 header{background:#fff;border-bottom:3px solid var(--brand);padding:.85rem 1.25rem;
   display:flex;align-items:center;gap:.9rem;flex-wrap:wrap}
 header img{height:34px}
 .tabs{display:flex;gap:1.1rem;align-items:center}
 .tabs a{color:var(--brand);font-weight:600;text-decoration:none;font-size:.9rem;padding-bottom:.2rem}
 .tabs a.on{color:var(--strong);border-bottom:2px solid var(--brand)}
 .out{margin-left:auto;color:var(--quiet);font-size:.85rem;text-decoration:none}
 .out:hover{color:var(--brand)}
 main{padding:1rem 1.25rem;max-width:1780px;margin:0 auto}
 @media(min-width:1100px){body{zoom:.75}main{max-width:2400px}}
 h2{font-family:Poppins,sans-serif;font-weight:600;color:var(--strong);margin:0 0 .3rem;font-size:.95rem}
 .layer{background:#fff;border:1px solid var(--line);border-radius:10px;padding:1rem;margin-bottom:1rem;
   border-left:5px solid var(--line)}
 .layer.green{border-left-color:#0b6e4f}
 .layer.amber{border-left-color:#b8860b}
 .layer.grey{border-left-color:#5a6068}
 .sub{color:var(--quiet);font-size:.85rem;margin:0 0 .6rem}
 table{width:100%;border-collapse:collapse}
 td{padding:.45rem 0;border-bottom:1px solid var(--line);font-size:.9rem}
 tr:last-child td{border-bottom:0}
 td.r{text-align:right;white-space:nowrap;color:var(--quiet)}
 .dot{display:inline-block;width:.62rem;height:.62rem;border-radius:50%;margin-right:.5rem}
 .quiet{color:var(--quiet)}
 .cards{columns:520px;column-gap:1rem}
 .cards .layer{break-inside:avoid}
</style></head><body>
<header>
  <img src="https://itsurgery.me/assets/logo.png" alt="IT Surgery">
  <nav class="tabs"><a href="/">Dashboard</a><a href="/monitoring">Monitoring</a><a href="/webmin-frame">Webmin</a><a class="on" href="/backup">Backup</a></nav>
  <a class="out" href="/oauth2/sign_out?rd=https%3A%2F%2Flogin.microsoftonline.com%2F0f8703ae-7d51-4894-b66e-75f73e64a903%2Foauth2%2Fv2.0%2Flogout%3Fpost_logout_redirect_uri%3Dhttps%253A%252F%252Fdashboard.itsurgery.me%252Fsigned-out">Sign out</a>
</header>
<main>
  <div class="cards">

  <div class="layer green">
    <h2>Layer 1 — nightly application dumps <span class="quiet">· live</span></h2>
    <p class="sub">Consistent database dumps and archives in /opt/&lt;service&gt;/backups on
    the VPS. This is the copy the other layers carry. It lives on the same
    disk as the services — a staging area, <strong>not</strong> a disaster copy.</p>
    <table>${dumpRows}</table>
  </div>

  <div class="layer green">
    <h2>Layer 2 — OVH automated backup <span class="quiet">· verified 28 Aug 2026</span></h2>
    <p class="sub">Enabled: OVH snapshots the whole VPS daily at 08:35 UTC,
    restorable from their panel — and 08:35 lands after the 02:30–03:15 dumps,
    so each snapshot carries that night's consistent exports.
    <strong>The standard tier keeps exactly one restore point</strong>:
    corruption noticed more than a day late is already in the only backup.
    Depth of history is Layer 3's job, which is why it matters.</p>
  </div>

  <div class="layer grey">
    <h2>Layer 3 — Proxmox Backup Server <span class="quiet">· waiting for the server</span></h2>
    <p class="sub">The data layer: nightly dumps pushed encrypted to PBS on our own
    hardware in the garage-office estate, with month-deep history, per-file
    restore and scheduled verification. The server is being brought online;
    the pbs-client role deploys the day it answers. Until then this layer
    protects nothing, and says so.</p>
  </div>

  <div class="layer green">
    <h2>What is protected, and by what</h2>
    <table>${coverage.map(([what, how, st]) =>
      `<tr><td>${dot(st)}${esc(what)}</td><td class="r">${esc(how)}</td></tr>`).join('')}
    </table>
    <p class="sub" style="margin-top:.6rem">Restore procedures live in the admin
    &amp; deployment guide. Until PBS is online, recovery from total VPS loss
    depends on Layer 2 — which is why its verification matters.</p>
  </div>

  </div>
</main></body></html>`;

return [{ json: { html } }];
